package cn.mop.exportworker;
import cn.mop.domain.DomainException;
import org.junit.jupiter.api.Test;
import java.time.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class ExportPreparationWorkerSettingsTest {
    static final String ID="59000000-0000-4000-8000-0000000000ab";
    static String[] args(){return new String[]{"--prepare-one-without-publication",ID};}
    static Map<String,String> valid(){return new HashMap<>(Map.of("SPRING_PROFILES_ACTIVE","remote_test","MOP_EXPORT_PREPARATION_WORKER_ENABLED","true","SPRING_DATASOURCE_URL","jdbc:postgresql://127.0.0.1:25432/mop_test","SPRING_DATASOURCE_USERNAME","mop_test_runtime","SPRING_DATASOURCE_PASSWORD","UNIT_ONLY_SECRET","MOP_EXPORT_PREPARATION_WORKER_ID","unit-export","MOP_EXPORT_PREPARATION_LEASE_MILLIS","30000"));}
    @Test void explicitValidSingleJobSettingsRetainTechnicalLeaseWithoutPrintingSecrets(){var s=ExportPreparationWorkerSettings.from(args(),valid()::get);assertEquals(ID,s.jobId());assertEquals(Duration.ofSeconds(30),s.lease());assertEquals("unit-export",s.workerId());assertFalse(s.toString().contains("UNIT_ONLY_SECRET"));assertFalse(s.toString().contains("jdbc:"));}
    @Test void omittedUnknownMixedOrNoncanonicalArgumentsAreRejected(){for(String[] a:Arrays.asList(null,new String[0],new String[]{"--prepare-one",ID},new String[]{"--prepare-one-without-publication"},new String[]{"--prepare-one-without-publication",ID,"extra"},new String[]{"--prepare-one-without-publication",ID.toUpperCase()},new String[]{"--prepare-one-without-publication","1-1-1-1-1"}))assertThrows(IllegalStateException.class,()->ExportPreparationWorkerSettings.from(a,valid()::get));}
    @Test void noFixtureProductionOrDefaultProfileIsAccepted(){for(String profile:Arrays.asList(null,"","local_fixture","production","remote_test,local_fixture"," remote_test ")){var env=valid();env.put("SPRING_PROFILES_ACTIVE",profile);assertThrows(IllegalStateException.class,()->ExportPreparationWorkerSettings.from(args(),env::get));}}
    @Test void dedicatedWorkerRequiresExactOptInAndRejectsOtherWorkerRoles(){for(String flag:Arrays.asList(null,"false","TRUE","1")){var env=valid();env.put("MOP_EXPORT_PREPARATION_WORKER_ENABLED",flag);assertThrows(IllegalStateException.class,()->ExportPreparationWorkerSettings.from(args(),env::get));}for(String key:List.of("MOP_PHOTO_WORKER_ENABLED","MOP_IMPORT_WORKER_ENABLED","MOP_ASSET_IMPORT_WORKER_ENABLED","MOP_CONTACT_IMPORT_WORKER_ENABLED")){var env=valid();env.put(key,"true");assertThrows(IllegalStateException.class,()->ExportPreparationWorkerSettings.from(args(),env::get));}}
    @Test void onlyRestrictedLoopbackDatabaseWithoutOptionsIsAccepted(){for(String url:List.of("jdbc:postgresql://example.invalid:5432/mop_test","jdbc:postgresql://localhost:25432/mop_test","jdbc:postgresql://127.0.0.1:0/mop_test","jdbc:postgresql://127.0.0.1:65536/mop_test","jdbc:postgresql://127.0.0.1:25432/other","jdbc:postgresql://127.0.0.1:25432/mop_test?password=UNIT_ONLY_SECRET")){var env=valid();env.put("SPRING_DATASOURCE_URL",url);var e=assertThrows(IllegalStateException.class,()->ExportPreparationWorkerSettings.from(args(),env::get));assertFalse(e.getMessage().contains("UNIT_ONLY_SECRET"));assertFalse(e.getMessage().contains(url));}}
    @Test void migrationIdentityAndMissingPrivatePasswordAreRejected(){for(String user:List.of("postgres","mop_test_migrator","other")){var env=valid();env.put("SPRING_DATASOURCE_USERNAME",user);assertThrows(IllegalStateException.class,()->ExportPreparationWorkerSettings.from(args(),env::get));}var env=valid();env.remove("SPRING_DATASOURCE_PASSWORD");assertThrows(IllegalStateException.class,()->ExportPreparationWorkerSettings.from(args(),env::get));}
    @Test void leaseIsRequiredCanonicalAndBounded(){for(String lease:Arrays.asList(null,"","0","999","600001","030000","1e3","1000.0","-1"," 1000","99999999999999999999999")){var env=valid();env.put("MOP_EXPORT_PREPARATION_LEASE_MILLIS",lease);assertThrows(IllegalStateException.class,()->ExportPreparationWorkerSettings.from(args(),env::get));}for(String lease:List.of("1000","600000")){var env=valid();env.put("MOP_EXPORT_PREPARATION_LEASE_MILLIS",lease);assertEquals(Long.parseLong(lease),ExportPreparationWorkerSettings.from(args(),env::get).lease().toMillis());}}
    @Test void workerLabelCannotContainUnboundedOrUnexpectedCharacters(){for(String worker:Arrays.asList(null,"","bad worker","x".repeat(65),"../worker")){var env=valid();env.put("MOP_EXPORT_PREPARATION_WORKER_ID",worker);assertThrows(IllegalStateException.class,()->ExportPreparationWorkerSettings.from(args(),env::get));}}
    @Test void failureCodeNeverEchoesExceptionOrConnectionContent(){assertEquals("CONFIGURATION_OR_COMPONENT_NOT_READY",ExportPreparationWorkerApplication.safeCode(new IllegalStateException("password=UNIT_ONLY_SECRET")));assertEquals("EXPORT_PREPARATION_FAILED",ExportPreparationWorkerApplication.safeCode(new Exception("jdbc:private")));assertEquals("LEASE_LOST",ExportPreparationWorkerApplication.safeCode(new DomainException(409,"LEASE_LOST","UNIT_ONLY_SECRET")));assertEquals("EXPORT_PREPARATION_FAILED",ExportPreparationWorkerApplication.safeCode(new DomainException(400,"UNSAFE\"CODE","UNIT_ONLY_SECRET")));}
    record DateProbe(LocalDate purchaseDate,Instant generatedAt){}
    @Test void mapperMatchesActualMetadataNamingAndDateModules()throws Exception{var mapper=ExportPreparationWorkerApplication.mapper();var probe=new DateProbe(LocalDate.parse("2026-10-04"),Instant.parse("2026-10-04T00:00:00Z"));String json=mapper.writeValueAsString(probe);assertTrue(json.contains("purchase_date"));assertTrue(json.contains("generated_at"));assertTrue(json.contains("2026-10-04T00:00:00Z"));assertEquals(probe,mapper.readValue(json,DateProbe.class));}
}
